const SIDEBAR_STORAGE_KEY='operators-journal-sidebar';
let sidebarOpen=true;
let mobileSidebarOpen=false;
let sidebarHoverCloseTimer=0;
let sidebarCloseClassTimer=0;
const sidebarHoverQuery=window.matchMedia('(min-width: 881px) and (hover: hover) and (pointer: fine)');
try{sidebarOpen=sidebarHoverQuery.matches?false:localStorage.getItem(SIDEBAR_STORAGE_KEY)!=='collapsed';}catch(_err){sidebarOpen=!sidebarHoverQuery.matches;}

function isMobileSidebar(){return window.matchMedia('(max-width: 880px)').matches;}
function usesHoverSidebar(){return sidebarHoverQuery.matches&&!isMobileSidebar();}
function applySidebarState(){
  const sidebar=document.getElementById('sidebar');
  const main=document.getElementById('main-content');
  const backdrop=document.getElementById('sidebar-backdrop');
  const mobileToggle=document.getElementById('mobile-sidebar-toggle');
  if(!sidebar||!main)return;
  const mobile=isMobileSidebar();
  if(mobile){
    sidebar.classList.toggle('mobile-open',mobileSidebarOpen);
    if(backdrop){backdrop.classList.toggle('visible',mobileSidebarOpen);backdrop.setAttribute('aria-hidden',mobileSidebarOpen?'false':'true');}
    document.body.classList.toggle('sidebar-drawer-open',mobileSidebarOpen);
    if(mobileToggle){mobileToggle.setAttribute('aria-expanded',mobileSidebarOpen?'true':'false');mobileToggle.setAttribute('aria-label',mobileSidebarOpen?'Close navigation':'Open navigation');}
  }else{
    mobileSidebarOpen=false;
    sidebar.classList.remove('mobile-open');
    sidebar.classList.toggle('collapsed',!sidebarOpen);
    /* Hover expansion floats above the workspace instead of shifting the page. */
    main.classList.toggle('expanded',usesHoverSidebar()||!sidebarOpen);
    if(backdrop){backdrop.classList.remove('visible');backdrop.setAttribute('aria-hidden','true');}
    document.body.classList.remove('sidebar-drawer-open');
    if(mobileToggle){mobileToggle.setAttribute('aria-expanded','false');mobileToggle.setAttribute('aria-label','Open navigation');}
  }
  const expanded=mobile?mobileSidebarOpen:sidebarOpen;
  document.querySelectorAll('.workspace-toggle-btn,.sidebar-collapsed-toggle').forEach(btn=>btn.setAttribute('aria-expanded',expanded?'true':'false'));
  const workspaceToggle=document.querySelector('.workspace-toggle-btn');
  if(workspaceToggle){workspaceToggle.title=mobile?'Close navigation':'Close sidebar';workspaceToggle.setAttribute('aria-label',workspaceToggle.title);}
}
function closeMobileSidebar(){
  if(!mobileSidebarOpen)return;
  mobileSidebarOpen=false;
  applySidebarState();
}
function toggleSidebar(){
  if(isMobileSidebar()){
    mobileSidebarOpen=!mobileSidebarOpen;
  }else{
    sidebarOpen=!sidebarOpen;
    try{localStorage.setItem(SIDEBAR_STORAGE_KEY,sidebarOpen?'open':'collapsed');}catch(_err){}
  }
  applySidebarState();
}
function openSidebarOnHover(){
  if(!usesHoverSidebar())return;
  window.clearTimeout(sidebarHoverCloseTimer);
  window.clearTimeout(sidebarCloseClassTimer);
  if(sidebarElement)sidebarElement.classList.remove('closing');
  if(sidebarOpen)return;
  sidebarOpen=true;
  applySidebarState();
}
function closeSidebarAfterHover(){
  if(!usesHoverSidebar())return;
  window.clearTimeout(sidebarHoverCloseTimer);
  sidebarHoverCloseTimer=window.setTimeout(()=>{
    if(!usesHoverSidebar()||!sidebarOpen)return;
    if(sidebarElement)sidebarElement.classList.add('closing');
    sidebarOpen=false;
    applySidebarState();
    window.clearTimeout(sidebarCloseClassTimer);
    sidebarCloseClassTimer=window.setTimeout(()=>{
      if(sidebarElement)sidebarElement.classList.remove('closing');
    },500);
  },170);
}
const sidebarElement=document.getElementById('sidebar');
if(sidebarElement){
  sidebarElement.addEventListener('mouseenter',openSidebarOnHover);
  sidebarElement.addEventListener('mouseleave',closeSidebarAfterHover);
}
applySidebarState();
window.addEventListener('resize',()=>{
  window.clearTimeout(sidebarHoverCloseTimer);
  window.clearTimeout(sidebarCloseClassTimer);
  if(sidebarElement)sidebarElement.classList.remove('closing');
  if(usesHoverSidebar())sidebarOpen=false;
  applySidebarState();
},{passive:true});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeMobileSidebar();});

