    '<div class="td-section"><div class="td-section-title">Notes &amp; Trade Review</div><div class="td-notes-box">'+esc(t.notes||'No notes recorded for this trade.')+'</div></div>'+
    '</div>';
  document.body.appendChild(overlay);
  loadDetailShots(id);
