  const funded=a.type==='funded',brokerOptions=TARGET_BROKERS.map(b=>`<option value="${b.id}" ${a.brokerId===b.id?'selected':''}>${esc(b.name)}</option>`).join('');
  const fields=funded?`<div class="target-live-form"><div class="target-field"><label>Account name</label><input id="edit-target-name" maxlength="60" value="${esc(a.accountName||'')}"></div><div class="target-field"><label>Account number</label><input id="edit-target-number" maxlength="40" autocomplete="off" value="${esc(a.accountNumber||'')}"></div><div class="target-field"><label>Account size (USD)</label><input id="edit-target-capital" type="number" min="1" step="1" value="${Number(a.accountSize||0)}"></div><div class="target-field"><label>Platform / broker</label><input id="edit-target-platform" maxlength="60" value="${esc(a.platform||'')}"></div><div class="target-field"><label>Purchase price (optional)</label><input id="edit-target-price" type="number" min="0" step="0.01" value="${Number(a.purchasePrice||0)}"></div><div class="target-field"><label>Sale / discount code</label><input id="edit-target-sale" maxlength="40" value="${esc(a.saleCode||'')}"></div><div class="funded-manual-note"><label>Additional rules</label><textarea id="edit-target-rules">${esc(a.additionalRules||'')}</textarea></div></div>`:`<div class="target-live-form"><div class="target-field"><label>Account name</label><input id="edit-target-name" maxlength="60" value="${esc(a.accountName||'')}"></div><div class="target-field"><label>Account number</label><input id="edit-target-number" maxlength="40" autocomplete="off" value="${esc(a.accountNumber||'')}"></div><div class="target-field"><label>Starting capital (${esc(a.currency||targetPlan().currency)})</label><input id="edit-target-capital" type="number" min="0.01" step="0.01" value="${Number(a.capital||0)}"></div><div class="target-broker-select-row"><div class="target-field"><label>Broker</label><select id="edit-target-broker" onchange="updateTargetEditBrokerPreview()">${brokerOptions}</select></div><div class="target-broker-preview" id="edit-target-broker-preview"></div></div></div>`;
  const roadmap=compoundingAccountSettings(a),profitLot=profitTargetLotSettings(a),roadmapFields=targetAccountMode(a)==='compounding'?`<div class="funded-rule-panel"><div class="funded-rule-head"><b>Roadmap settings</b><span class="target-sub">Capital and currency come from this account</span></div><div class="target-live-form"><div class="target-field"><label>Trading days</label><input id="edit-roadmap-days" type="number" min="1" max="365" step="1" value="${roadmap.days}"></div><div class="target-field"><label>Daily target (%)</label><input id="edit-roadmap-rate" type="number" min="0" max="50" step="0.1" value="${roadmap.rate}"></div><div class="target-field"><label>Maximum daily loss (%)</label><input id="edit-roadmap-loss" type="number" min="0" max="50" step="0.1" value="${roadmap.loss}"></div><div class="target-field"><label>Minimum target move (pips)</label><input id="edit-roadmap-min-pips" type="number" min="1" max="10000" step="1" value="${roadmap.minPips}"></div><div class="target-field"><label>Maximum target move (pips)</label><input id="edit-roadmap-max-pips" type="number" min="1" max="10000" step="1" value="${roadmap.maxPips}"></div></div><div class="compound-lot-settings-note"><b>XAUUSD lot range</b><span>Uses $1 per pip for 1.00 standard lot. A smaller target move requires a larger lot.</span></div></div>`:'',profitLotFields=targetAccountMode(a)==='profit'?`<div class="funded-rule-panel profit-lot-settings"><div class="funded-rule-head"><b>Profit Target lot settings</b><span class="target-sub">Saved separately for this Profit Target account</span></div><div class="target-live-form"><div class="target-field"><label>Minimum target move (pips)</label><input id="edit-profit-min-pips" type="number" min="1" max="10000" step="1" value="${profitLot.minPips}"></div><div class="target-field"><label>Maximum target move (pips)</label><input id="edit-profit-max-pips" type="number" min="1" max="10000" step="1" value="${profitLot.maxPips}"></div></div><div class="compound-lot-settings-note"><b>XAUUSD lot range</b><span>Uses $1 per pip for 1.00 standard lot. Carry-forward changes the assigned target automatically.</span></div></div>`:'',accountSettings=roadmapFields||profitLotFields;
  box.innerHTML=`<div class="target-modal"><div class="target-modal-head"><div><h2>${roadmapFields?'Account & Roadmap Settings':profitLotFields?'Account & Target Lot Settings':'Edit Account'}</h2><div class="target-sub">Update the selected ${funded?'Funded':'Live'} Account${roadmapFields?' and its Compounding Roadmap':profitLotFields?' and its Profit Target lot assumptions':''}.</div></div><button class="target-modal-close" onclick="closeTargetAccountModal()">×</button></div>${fields}${accountSettings}<div class="target-modal-actions"><button class="target-btn danger" onclick="deleteTargetAccountFromEditor('${a.id}')">Delete Account</button><button class="target-btn" onclick="closeTargetAccountModal()">Cancel</button><button class="target-btn primary" onclick="saveTargetAccountEdits('${a.id}')">Save Changes</button></div></div>`;
  document.body.appendChild(box);
