  const badgeUnlocks = LW_BADGES.map(b=>({...b, unlocked:hasTrades && b.test(myScores)}));
  const dna = lwBuildDnaNarrative(myScores, hasTrades);
  const pwData = hasTrades ? lwPerfectWeeks() : {count:0, weeks:[]};
